export async function run({ page, name }) {
  if (!name) {
    throw new Error('name is required');
  }
  const expectedStatus = `done-${name}`;
  const html =
    `<h1>${name}</h1>` +
    `<button>Continue ${name}</button>` +
    `<div role="status" id="status">ready</div>` +
    `<script>document.querySelector('button').addEventListener('click',()=>{document.getElementById('status').textContent='done-${name}';});</script>`;
  await page.setContent(html);
  await page.getByRole('button', { name: `Continue ${name}` }).click();
  await page.waitForFunction(
    (expected) => document.getElementById('status')?.textContent === expected,
    expectedStatus,
    { timeout: 5000 }
  );
  const status = (await page.getByRole('status').textContent()) ?? '';
  if (status !== expectedStatus) {
    throw new Error(`status mismatch: expected ${expectedStatus} got ${status}`);
  }
  const heading = (await page.getByRole('heading', { level: 1 }).textContent()) ?? '';
  if (heading !== name) {
    throw new Error(`heading mismatch: expected ${name} got ${heading}`);
  }
  return { name, status };
}

